#!/usr/bin/env python
"""tables/d6_logged.tex from raea4/depth/results_D6.json (inherited histories generated by fixed logging policies).
Usage: python paper/scripts/make_d6_table.py
Also prints the numbers quoted in the appendix paragraph."""
import json
from pathlib import Path

SRC = Path(__file__).resolve().parents[2] / "raea4" / "depth" / "results_D6.json"
OUT = Path(__file__).resolve().parents[1] / "tables/d6_logged.tex"
R = json.load(open(SRC, encoding="utf-8"))
F = ["RETRY", "SHARED"]

def sg(x, d=2):
    s = f"{abs(x):.{d}f}"
    return ("$-$" if x < 0 and float(s) != 0 else "") + s

def ci(e, k="regret", lo="lo", hi="hi"):
    return f"{sg(e[k])}\\,\\simci{{{sg(e[lo])}}}{{{sg(e[hi])}}}"

POL_A = [("Fitted dependence, keep all", "Fitted dependence (keep all)"),
         ("Fitted dependence, forbid", "Fitted dependence + forbid"),
         ("Fitted independent, forbid", "Fitted indep + forbid"),
         ("Fitted independent, first report per source", "Fitted indep, first report"),
         ("Fitted independent, pool by source + forbid", "Fitted indep, pool + forbid"),
         ("MMI, forbid", "MMI + forbid"),
         ("MMI, first report per source", "MMI, first report"),
         ("MMI, pool by source + forbid", "MMI, pool + forbid"),
         ("Fault-unaware, keep all", "Fault-unaware (keep all)")]
POL_B = [POL_A[0], POL_A[2], POL_A[3], POL_A[4], POL_A[5], POL_A[7]]
LOGS = [("retry-heavy", "retry"), ("round-robin", "round-robin"), ("random", "random"),
        ("myopic fault-unaware", "myopic"), ("MMI planner", "MMI plan")]

def row(c): return " & ".join(c) + " \\\\"

L = ["% generated by scripts/make_d6_table.py -- do not edit by hand",
     f"% src: raea4/depth/results_D6.json (script raea4/depth/D6_logged_histories.py; seed 402, 300 instances per family, fitted n=100)",
     "\\begin{tabular}{@{}l cc cc@{}}", "\\toprule",
     r"& \multicolumn{2}{c}{all histories} & \multicolumn{2}{c}{given a same-source repeat} \\",
     r"Continuation policy & \textsc{retry} & \textsc{shared} & \textsc{retry} & \textsc{shared} \\", "\\midrule",
     r"\multicolumn{5}{@{}l}{\emph{A. Pooled over five logging policies and history lengths 1--4}} \\"]
for lab, key in POL_A:
    a = [R[f]["pooled"]["all_L1-4"][key] for f in F]
    L.append(row([lab, ci(a[0]), ci(a[1]), ci(a[0], "regret_given_repeat", "lo_rep", "hi_rep"),
                  ci(a[1], "regret_given_repeat", "lo_rep", "hi_rep")]))
    L.append(f"% src: pooled.all_L1-4[{key}].regret/.regret_given_repeat")
pr = [R[f]["pooled"]["all_L1-4"]["MMI + forbid"]["p_repeat"] for f in F]
L.append(row([r"Share of histories with a same-source repeat", sg(pr[0]), sg(pr[1]), "1", "1"]))
L.append("% src: pooled.all_L1-4[*].p_repeat")
L.append("\\bottomrule")
L.append("\\end{tabular}")
# panel B as its own tabular (different columns)
L.append("\\\\[4pt]")
L.append(r"{\emph{B. By logging policy (histories of length 2--4); regret \textsc{retry} / \textsc{shared}}}\\[2pt]")
L.append("\\begin{tabular}{@{}l ccccc@{}}")
L.append("\\toprule")
L.append(row(["Continuation policy"] + [f"\\makecell{{{n}}}" if False else n for _, n in LOGS]))
L.append("\\midrule")
for lab, key in POL_B:
    c = [lab]
    for lp, _ in LOGS:
        v = [R[f]["by_logger"][lp][key]["regret"] for f in F]
        c.append(f"{sg(v[0])} / {sg(v[1])}")
    L.append(row(c))
    L.append(f"% src: by_logger[*][{key}].regret")
c = ["Share with same-source repeat"]
for lp, _ in LOGS:
    v = [R[f]["by_logger"][lp]["MMI + forbid"]["p_repeat"] for f in F]
    c.append(f"{sg(v[0])} / {sg(v[1])}")
L.append(row(c)); L.append("% src: by_logger[*][*].p_repeat")
L += ["\\bottomrule", "\\end{tabular}", ""]
OUT.write_text("\n".join(L), encoding="utf-8")
print("wrote", OUT)
for f in F:
    d = R[f]
    print(f, "pooled all:", {k: round(d["pooled"]["all_L1-4"][k]["regret"], 2) for _, k in POL_A})
    for lp, _ in LOGS:
        print(" ", lp, {k[:10]: round(d["by_logger"][lp][k]["regret"], 2) for _, k in POL_B})
